export type TeamParam = Name;

export type TokenIdParam = string;

export type SshKeyIdParam = string;

export type GrantIdParam = string;

/**
 * Slug del provider OIDC.
 */
export type OidcProviderParam = Name;

/**
 * Branch, tag o sha (completo o prefisso di almeno 7 caratteri). Se manca vale il branch principale del repo (R4). Un nome non valido (vuoto, con `..`, spazi, caratteri di controllo o oltre 255 caratteri) risponde 400 `invalid_ref`; uno valido ma inesistente 404 `ref_not_found`. Se un nome e' sia branch sia tag vince il branch.
 *
 */
export type RefParam = string;

/**
 * Branch, tag o sha, sempre esplicito: core sostituisce il branch principale prima di chiamare il servizio git. Stesse regole di `RefParam` per 400 `invalid_ref` e 404 `ref_not_found`.
 *
 */
export type GitRefParam = string;

/**
 * Percorso relativo alla radice del repo, con `/` come separatore, senza `/` iniziale e senza segmenti `.` o `..` (400 `invalid_path`). Assente o vuoto: la radice.
 *
 */
export type PathParam = string;

/**
 * Percorso del file (stesse regole di `PathParam`, non vuoto).
 */
export type FilePathParam = string;

/**
 * Solo i commit il cui autore ha questo nome o email (senza distinguere maiuscole).
 */
export type CommitAuthorFilter = string;

export type CommitPageParam = number;

/**
 * Commit per pagina (default 30, massimo 100).
 */
export type CommitPerPageParam = number;

/**
 * Formato dell'archivio (default `zip`).
 */
export type ArchiveFormatParam = 'zip' | 'tar.gz';

/**
 * `patch` (default): formato mbox di `git format-patch` con autore, data e messaggio, scaricato come `.patch`; `diff`: solo il diff unificato, scaricato come `.diff`.
 *
 */
export type PatchFormatParam = 'diff' | 'patch';

/**
 * B6, «ignora spazi»: diff calcolato con `git diff -w`. Default false.
 */
export type IgnoreWhitespaceParam = boolean;

/**
 * Se presente, `files` porta solo questo file (core filtra la risposta del servizio git). Con `listOnly` il patch non c'e': per il diff intero si usa `getRepositoryCommitPatch`. 404 se il file non e' nel commit.
 *
 */
export type DiffFilePathParam = string;

/**
 * Coda del percorso: `<ref>/<percorso del file>`, su piu' segmenti. Un ref puo' contenere `/`: core prende il prefisso piu' lungo che e' il nome di un branch, altrimenti di un tag, altrimenti interpreta il primo segmento come sha (completo o prefisso di almeno 7 caratteri); il resto e' il percorso (stesse regole di `PathParam`, non vuoto). Se un nome e' sia branch sia tag vince il branch.
 *
 */
export type RefAndPathParam = string;

/**
 * Testo da cercare (sottostringa letterale, senza distinguere maiuscole), da 2 a 256 caratteri.
 */
export type CodeSearchQueryParam = string;

/**
 * Sha del commit, completo o prefisso univoco di almeno 7 caratteri esadecimali.
 */
export type CommitShaParam = string;

/**
 * Numero `#n` della issue nel repo (I1).
 */
export type IssueNumberParam = number;

/**
 * Id del commento.
 */
export type IssueCommentIdParam = string;

/**
 * Id dell'allegato.
 */
export type IssueAttachmentIdParam = string;

/**
 * Nome dell'etichetta, codificato come componente di percorso (puo' contenere spazi, es. `good first issue`).
 *
 */
export type LabelNameParam = string;

/**
 * Numero della milestone nel repo (indipendente da quello delle issues).
 */
export type MilestoneNumberParam = number;

/**
 * Ricerca con la sintassi di I10: `is:open|closed`, `reason:completed|not_planned|duplicate`, `label:"nome"`, `assignee:utente|@me|@agents`, `author:`, `milestone:`, `no:label|assignee|milestone`, `repo:owner/nome`, `org:`, piu' testo libero.
 *
 */
export type IssueQueryParam = string;

export type IssueStateFilter = 'open' | 'closed' | 'all';

export type IssueReasonFilter = IssueCloseReason;

/**
 * Nomi di etichette separati da virgola; la issue le ha tutte.
 */
export type IssueLabelsFilter = string;

/**
 * Nome utente, `@me`, `@agents` (assegnata a un agente) o `none`.
 */
export type IssueAssigneeFilter = string;

export type IssueAuthorFilter = string;

/**
 * Numero della milestone, o `none`.
 */
export type IssueMilestoneFilter = string;

/**
 * Ordinamento decrescente; `relevance` solo con testo libero in `q` (altrimenti 422).
 *
 */
export type IssueSortParam = 'created' | 'updated' | 'comments' | 'relevance';

export type MilestoneStateFilter = 'open' | 'closed' | 'all';

export type NotificationIdParam = string;

/**
 * Uno o piu' motivi (`NotificationReason`) separati da virgola, es. `assigned,mentioned`. Un motivo sconosciuto: 400.
 *
 */
export type NotificationReasonFilter = string;

export type NotificationStateFilter = 'unread' | 'read' | 'archived' | 'all';

/**
 * Solo le notifiche di un repo, `owner/repo`.
 */
export type NotificationRepoFilter = string;

export type WebhookIdParam = string;

export type WebhookDeliveryIdParam = string;

